26	Status TransShapeNchwToNc1hwc0(const std::vector<int64_t> &src_shape, const DataType data_type, const int64_t cube_size,
27	                               std::vector<int64_t> &dst_shape) {
28	  int64_t c0 = (cube_size <= 0) ? GetCubeSizeByDataType(data_type) : cube_size;
29	  if (c0 <= 0) {
30	    GELOGE(ACL_ERROR_GE_DATATYPE_INVALID, "[Get][Cube]Failed, the data type %s is invalid",
31	           TypeUtilsInner::DataTypeToSerialString(data_type).c_str());
32	    REPORT_INNER_ERR_MSG("E19999", "Failed to get cube size, the data type %s is invalid",
33	                         TypeUtilsInner::DataTypeToSerialString(data_type).c_str());
34	    return ACL_ERROR_GE_DATATYPE_INVALID;
35	  }
36	  if (!CheckShapeValid(src_shape, kNchwDimsNum)) {
37	    GELOGE(ACL_ERROR_GE_SHAPE_INVALID, "[Check][Shape]Value is invalid, src shape %s",
38	           ShapeToString(src_shape).c_str());
39	    REPORT_INNER_ERR_MSG("E19999", "Src shape %s check invalid", ShapeToString(src_shape).c_str());
40	    return ACL_ERROR_GE_SHAPE_INVALID;
41	  }
42	  dst_shape.clear();
43	  dst_shape.push_back(src_shape.at(kNchwN));
44	  dst_shape.push_back(Ceil(src_shape.at(kNchwC), c0));
45	  dst_shape.push_back(src_shape.at(kNchwH));
46	  dst_shape.push_back(src_shape.at(kNchwW));
47	  dst_shape.push_back(c0);
48	  if (!CheckShapeValid(dst_shape, kNc1hwc0DimsNum)) {
49	    GELOGE(ACL_ERROR_GE_SHAPE_INVALID, "[Check][Shape]Value is invalid, dst shape %s",
50	           ShapeToString(dst_shape).c_str());
51	    REPORT_INNER_ERR_MSG("E19999", "Dst shape %s check invalid", ShapeToString(dst_shape).c_str());
52	    return ACL_ERROR_GE_SHAPE_INVALID;
53	  }
54	  return SUCCESS;
55	}
56	
57	Status CheckArgsForNchwToNc1hwc0(const TransArgs &args) {
58	  if ((args.src_primary_format != FORMAT_NCHW) || (args.dst_primary_format != FORMAT_NC1HWC0)) {
59	    const std::string error = "Dose not support trans format from " +
60	                              FmtToStr(TypeUtilsInner::FormatToSerialString(args.src_primary_format)) + " to " +
61	                              FmtToStr(TypeUtilsInner::FormatToSerialString(args.dst_primary_format));
62	    GE_ERRORLOG_AND_ERRORMSG(ACL_ERROR_GE_FORMAT_INVALID, error.c_str());
63	    return ACL_ERROR_GE_FORMAT_INVALID;
64	  }
65	  std::vector<int64_t> expect_5d_shape;
66	  const int64_t c0 = GetC0Value(static_cast<int32_t>(args.dst_format));
67	  const auto ret = TransShapeNchwToNc1hwc0(args.src_shape, args.src_data_type, c0, expect_5d_shape);
68	  if (ret != SUCCESS) {
69	    return ret;
70	  }
71	  if (expect_5d_shape != args.dst_shape) {
72	    GELOGE(ACL_ERROR_GE_SHAPE_INVALID,
73	           "[Trans][Format]Failed, the src and dst shape are not compatible. "
74	           "data type %s, src shape %s, dst shape %s, expect dst shape %s",
75	           TypeUtilsInner::DataTypeToSerialString(args.src_data_type).c_str(), ShapeToString(args.src_shape).c_str(),
76	           ShapeToString(args.dst_shape).c_str(), ShapeToString(expect_5d_shape).c_str());
77	    REPORT_INNER_ERR_MSG("E19999",
78	                         "Failed to trans formats, the src and dst shape are not "
79	                         "compatible. data type %s, src shape %s, dst shape %s, expect dst shape %s",
80	                         TypeUtilsInner::DataTypeToSerialString(args.src_data_type).c_str(),
81	                         ShapeToString(args.src_shape).c_str(), ShapeToString(args.dst_shape).c_str(),
82	                         ShapeToString(expect_5d_shape).c_str());
83	    return ACL_ERROR_GE_SHAPE_INVALID;
84	  }
85	
86	  return SUCCESS;
