89	Status GetDstDataAfterTransOfNchw2Nc1hwc0(const TransArgs &args, TransResult &result, const int32_t size,
90	                                          const int64_t total_size) {
91	  const std::shared_ptr<uint8_t> dst(new (std::nothrow) uint8_t[total_size], std::default_delete<uint8_t[]>());
92	  if (dst == nullptr) {
93	    GELOGE(ACL_ERROR_GE_MEMORY_ALLOCATION,
94	           "[Allocate][Memory]Failed to alloc the memory for dst buf %" PRId64
95	           ", "
96	           "shape %s when trans format from %s to %s",
97	           total_size, ShapeToString(args.dst_shape).c_str(),
98	           TypeUtilsInner::FormatToSerialString(args.src_format).c_str(),
99	           TypeUtilsInner::FormatToSerialString(args.dst_format).c_str());
100	    REPORT_INNER_ERR_MSG("E19999",
101	                         "Failed to alloc the memory for dst buf %" PRId64
102	                         ", "
103	                         "shape %s when trans format from %s to %s",
104	                         total_size, ShapeToString(args.dst_shape).c_str(),
105	                         TypeUtilsInner::FormatToSerialString(args.src_format).c_str(),
106	                         TypeUtilsInner::FormatToSerialString(args.dst_format).c_str());
107	    return ACL_ERROR_GE_MEMORY_ALLOCATION;
108	  }
109	
110	  const auto n = args.src_shape.at(kNchwN);
111	  const auto c = args.src_shape.at(kNchwC);
112	  const auto h = args.src_shape.at(kNchwH);
113	  const auto w = args.src_shape.at(kNchwW);
114	
115	  const int64_t c0 = GetC0Value(static_cast<int32_t>(args.dst_format));
116	  if (c0 <= 0) {
117	    GELOGE(ACL_ERROR_GE_DATATYPE_INVALID, "[Check][Shape]The c0 is invalid %" PRId64 ", data_type %s", c0,
118	           TypeUtilsInner::DataTypeToSerialString(args.src_data_type).c_str());
119	    REPORT_INNER_ERR_MSG("E19999", "Check shape failed, the c0 is invalid %" PRId64 ", data_type %s", c0,
120	                         TypeUtilsInner::DataTypeToSerialString(args.src_data_type).c_str());
121	    return ACL_ERROR_GE_DATATYPE_INVALID;
122	  }
123	  const int64_t c1 = ((c - 1) / c0) + 1;
124	  const int64_t hw = h * w;
125	  const int64_t hwc0 = hw * c0;
126	  const int64_t c1hwc0 = c1 * hwc0;
127	
128	  for (int64_t n_idx = 0; n_idx < n; n_idx++) {
129	    const int64_t n_head_addr = n_idx * c1hwc0;
130	    for (int64_t c1_idx = 0; c1_idx < c1; c1_idx++) {
131	      const int64_t c1_head_addr = n_head_addr + (c1_idx * hwc0);
132	      for (int64_t h_idx = 0; h_idx < h; h_idx++) {
133	        const int64_t wc0 = w * c0;
134	        const int64_t h_head_addr = c1_head_addr + (h_idx * wc0);
135	        for (int64_t w_idx = 0; w_idx < w; w_idx++) {
136	          const int64_t w_head_addr = h_head_addr + (w_idx * c0);
137	          for (int64_t c0_idx = 0; c0_idx < c0; c0_idx++) {
138	            const int64_t dst_index = c0_idx + w_head_addr;
139	            const int64_t dst_offset = dst_index * size;
140	            const auto protected_size = ((total_size - dst_offset) < static_cast<int64_t>(SECUREC_MEM_MAX_LEN))
141	                                            ? (total_size - dst_offset)
142	                                            : static_cast<int64_t>(SECUREC_MEM_MAX_LEN);
143	            GE_CHECK_GE(protected_size, 0);
144	            const int64_t cIdx = c0_idx + (c1_idx * c0);
145	
146	            if (cIdx < c) {
147	              const int64_t chw = c * hw;
148	              const int64_t srcIdx = (n_idx * chw) + (cIdx * hw) + (h_idx * w) + w_idx;
149	              const auto src_offset = srcIdx * size;
150	              const auto ret =
151	                  memcpy_s(PtrAdd(dst.get(), static_cast<size_t>(total_size), static_cast<size_t>(dst_offset)),
152	                           static_cast<size_t>(protected_size), args.data + src_offset, static_cast<size_t>(size));
153	              if (ret != EOK) {
154	                GELOGE(ACL_ERROR_GE_MEMORY_OPERATE_FAILED,
155	                       "[Operate][Memory]Failed to copy data from NCHW[%" PRId64 "] offset %" PRId64
156	                       " "
157	                       "to NC1HWC0[%" PRId64 ", %" PRId64 ", %" PRId64 ", %" PRId64 ", %" PRId64
158	                       "] offset "
159	                       "%" PRId64 ", err-code %d",
160	                       srcIdx, src_offset, n_idx, c1_idx, h_idx, w_idx, c0_idx, dst_offset, ret);
161	                REPORT_INNER_ERR_MSG("E19999",
162	                                     "Failed to copy data from NCHW[%" PRId64 "] offset %" PRId64
163	                                     " "
164	                                     "to NC1HWC0[%" PRId64 ", %" PRId64 ", %" PRId64 ", %" PRId64 ", %" PRId64
165	                                     "] "
166	                                     "offset %" PRId64 ", err-code %d",
167	                                     srcIdx, src_offset, n_idx, c1_idx, h_idx, w_idx, c0_idx, dst_offset, ret);
168	                return ACL_ERROR_GE_MEMORY_OPERATE_FAILED;
169	              }
170	            } else {
171	              const auto ret =
172	                  memset_s(PtrAdd(dst.get(), static_cast<size_t>(total_size), static_cast<size_t>(dst_offset)),
173	                           static_cast<size_t>(protected_size), 0, static_cast<size_t>(size));
174	              if (ret != EOK) {
175	                GELOGE(ACL_ERROR_GE_MEMORY_OPERATE_FAILED,
176	                       "[Operate][Memory]Failed to set to 0 to NC1HWC0[%" PRId64 ", %" PRId64 ", %" PRId64
177	                       ", "
178	                       "%" PRId64 ", %" PRId64 "] offset %" PRId64 ", err-code %d",
179	                       n_idx, c1_idx, h_idx, w_idx, c0_idx, dst_offset, ret);
180	                REPORT_INNER_ERR_MSG("E19999",
181	                                     "Failed to set to 0 to "
182	                                     "NC1HWC0[%" PRId64 ", %" PRId64 ", %" PRId64 ", %" PRId64 ", %" PRId64
183	                                     "] "
184	                                     "offset %" PRId64 ", err-code %d",
185	                                     n_idx, c1_idx, h_idx, w_idx, c0_idx, dst_offset, ret);
186	                return ACL_ERROR_GE_MEMORY_OPERATE_FAILED;
187	              }
188	            }
189	          }
190	        }
191	      }
192	    }
193	  }
194	
195	  result.data = dst;
196	  result.length = static_cast<size_t>(total_size);
197	  return SUCCESS;
198	}
199	}  // namespace
200	
201	Status FormatTransferNchwNc1hwc0::TransFormat(const TransArgs &args, TransResult &result) {
202	  Status ret = CheckArgsForNchwToNc1hwc0(args);
203	  if (ret != SUCCESS) {
204	    return ret;
205	  }
206	  // Guarantee the validity of parameters in check function
207	  const int32_t size = GetSizeByDataType(args.src_data_type);
208	  const auto total_size = GetItemNumByShape(args.dst_shape) * size;
209	  if (total_size <= 0) {
210	    const int64_t src_size = GetItemNumByShape(args.src_shape);
211	    if ((total_size == 0) && (src_size == 0)) {
212	      result.length = static_cast<size_t>(total_size);
213	      return SUCCESS;
214	    }
215	
216	    GELOGE(ACL_ERROR_GE_SHAPE_INVALID,
217	           "[Get][Shape]Failed, total size %" PRId64
218	           " from dst shape %s, "
219	           "src shape %s",
220	           total_size, ShapeToString(args.dst_shape).c_str(), ShapeToString(args.src_shape).c_str());
221	    REPORT_INNER_ERR_MSG("E19999", "Failed to get total size %" PRId64 " from dst shape %s, src shape %s", total_size,
222	                         ShapeToString(args.dst_shape).c_str(), ShapeToString(args.src_shape).c_str());
223	    return ACL_ERROR_GE_SHAPE_INVALID;
224	  }
225	  GELOGD(
226	      "Begin to trans format from NCHW to NC1HWC0, src shape %s, data type "
227	      "%s, dst shape %s memory size %" PRId64 "",
228	      ShapeToString(args.src_shape).c_str(), TypeUtilsInner::DataTypeToSerialString(args.src_data_type).c_str(),
229	      ShapeToString(args.dst_shape).c_str(), total_size);
230	  ret = GetDstDataAfterTransOfNchw2Nc1hwc0(args, result, size, total_size);
231	  if (ret != SUCCESS) {
232	    GELOGE(ret,
233	           "[Get][Data]Failed, after trans, src shape %s, data type %s, "
234	           "dst shape %s, memory size %" PRId64 ", error_code %u",
235	           ShapeToString(args.src_shape).c_str(), TypeUtilsInner::DataTypeToSerialString(args.src_data_type).c_str(),
236	           ShapeToString(args.dst_shape).c_str(), total_size, ret);
237	    REPORT_INNER_ERR_MSG("E19999",
238	                         "Failed to get data after trans, src shape %s, data type %s, "
239	                         "dst shape %s, memory size %" PRId64 ", error_code %u",
240	                         ShapeToString(args.src_shape).c_str(),
241	                         TypeUtilsInner::DataTypeToSerialString(args.src_data_type).c_str(),
242	                         ShapeToString(args.dst_shape).c_str(), total_size, ret);
243	    return ret;
244	  }
245	  return SUCCESS;
246	}
247	
248	Status FormatTransferNchwNc1hwc0::TransShape(const Format src_format, const std::vector<int64_t> &src_shape,
249	                                             const DataType data_type, const Format dst_format,
250	                                             std::vector<int64_t> &dst_shape) {
251	  const Format src_primary_format = static_cast<Format>(GetPrimaryFormat(static_cast<int32_t>(src_format)));
252	  (void)dst_format;
253	  const auto c0 = GetC0Value(static_cast<int32_t>(dst_format));
254	  if (src_primary_format == FORMAT_NCHW) {
255	    return TransShapeNchwToNc1hwc0(src_shape, data_type, c0, dst_shape);
256	  } else {
257	    return ACL_ERROR_GE_FORMAT_INVALID;
258	  }
259	}
260	
261	REGISTER_FORMAT_TRANSFER(FormatTransferNchwNc1hwc0, FORMAT_NCHW, FORMAT_NC1HWC0)
262	}  // namespace formats
263	}  // namespace ge
