bool CheckDataTypeSupportedForNc1hwc0ToNchw(const DataType data_type) {
  return GetSizeByDataType(data_type) > 0;
}

Status CheckArgsForNc1hwc0ToNchw(const TransArgs &args) {
  const auto &src_shape = args.src_shape;
  const auto &dst_shape = args.dst_shape;
  if ((args.src_primary_format != FORMAT_NC1HWC0) || (args.dst_primary_format != FORMAT_NCHW)) {
    const std::string error = "Dose not support trans format from " +
                              FmtToStr(TypeUtilsInner::FormatToSerialString(args.src_primary_format)) + " to " +
                              FmtToStr(TypeUtilsInner::FormatToSerialString(args.dst_primary_format));
    GE_ERRORLOG_AND_ERRORMSG(ACL_ERROR_GE_FORMAT_INVALID, error.c_str());
    return ACL_ERROR_GE_FORMAT_INVALID;
  }
  if (!CheckDataTypeSupportedForNc1hwc0ToNchw(args.src_data_type)) {
    GELOGE(ACL_ERROR_GE_DATATYPE_INVALID,
           "[Check][DataType]Failed, shape from NC1HWC0 to NCHW, "
           "invalid data type %s",
           TypeUtilsInner::DataTypeToSerialString(args.src_data_type).c_str());
    REPORT_INNER_ERR_MSG("E19999", "Failed to trans shape from NC1HWC0 to NCHW, invalid data type %s",
                         TypeUtilsInner::DataTypeToSerialString(args.src_data_type).c_str());
    return ACL_ERROR_GE_DATATYPE_INVALID;
  }
  if (!CheckShapeValid(args.src_shape, kNc1hwc0DimsNum)) {
    GELOGE(ACL_ERROR_GE_SHAPE_INVALID, "[Check][Shape]Value is invalid, src shape %s",
           ShapeToString(args.src_shape).c_str());
    REPORT_INNER_ERR_MSG("E19999", "Src shape %s check invalid", ShapeToString(args.src_shape).c_str());
    return ACL_ERROR_GE_SHAPE_INVALID;
  }
  if (!CheckShapeValid(args.dst_shape, kNchwDimsNum)) {
    GELOGE(ACL_ERROR_GE_SHAPE_INVALID, "[Check][Shape]Value is invalid, dst shape %s",
           ShapeToString(args.dst_shape).c_str());
    REPORT_INNER_ERR_MSG("E19999", "Dst shape %s check invalid", ShapeToString(args.dst_shape).c_str());
    return ACL_ERROR_GE_SHAPE_INVALID;
  }

